'use client'

import * as React from 'react'

import { useStrings, type StringsOverrides } from './strings'
import { CrossGlyph } from './glyphs'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled ModerationNotice, and `tsc --noEmit` passes
// on it, so the gate cannot catch it.
import './moderation-notice.css'

// The shared rule sets, so the theme's action face and press gesture reach the
// menu entries. GSUI-118: the file shipped with the tokens and nothing imported
// it, so the classes matched nothing in a real install.
import './gamestage-primitives.css'

/**
 * ModerationNotice: what a player is told, and what they can do about somebody
 * else.
 *
 * Specimen 6d, in two treatments. The notice names the cause and the next
 * action: no apology, no "something went wrong", and above all no silence,
 * because a player whose message vanishes without a word learns only that the
 * room is broken. The menu is the other half: three worded entries, each 48px,
 * rather than a row of bare icons where report and block are one slip apart.
 *
 * The block entry says what the player gets rather than what happens to the
 * other person. A report confirms elsewhere and changes nothing here, so the
 * room cannot work out who reported.
 *
 * It decides nothing and sends nothing. The words naming which rule was broken
 * are the host's, because the library does not know the house rules, and the
 * link to them is a node the host passes rather than a target built from a
 * prop.
 */

export type ModerationNoticePresentation = 'notice' | 'menu'

export interface ModerationNoticeProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides

  /** `notice` is what the player is told. `menu` is what they can do. */
  presentation?: ModerationNoticePresentation

  /** Which notice. `refused` did not post; `held` still might. */
  moderation?: 'refused' | 'held'
  /** The heading. Defaults to the wording for this state. */
  heading?: string
  /**
   * Why, in words, and what to do next. Host copy, because only the host knows
   * which of its house rules the message broke.
   */
  reason?: React.ReactNode
  /**
   * The way to the house rules, as a node: the host's own link, its own router,
   * its own target. The library builds no link from a prop.
   */
  rules?: React.ReactNode

  /** Whose message the menu is about. Named in the block entry, so it is plain. */
  author?: string
  /** Quote them back. Absent and there is no reply entry. */
  onReply?: () => void
  /** Send it to the moderators. Absent and there is no report entry. */
  onReport?: () => void
  /** Hide everything from this player. Absent and there is no block entry. */
  onBlock?: () => void
}

/**
 * Emphasis a player can see without colour and read without sight, on the held
 * notice. There is no alert mark in the shared glyph set on this branch, which
 * is GSUI-262; `tip` types the same character for the same reason.
 */
const HELD_MARK = '!'

export function ModerationNotice(props: ModerationNoticeProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)

  const {
    presentation = 'notice',
    moderation = 'refused',
    heading,
    reason,
    rules,
    author,
    onReply,
    onReport,
    onBlock,
    className,
    children,
    ...rest
  } = componentProps

  const refused = moderation === 'refused'

  if (presentation === 'menu') {
    return (
      <div
        {...rest}
        className={['gs-moderation-notice', className].filter(Boolean).join(' ')}
        data-gs-component="moderation-notice"
        data-gs-presentation="menu"
        role="group"
        aria-label={author === undefined ? copy['moderation-notice.menuLabel'] : copy['moderation-notice.menuLabelFor'](author)}
      >
        <div className="gs-moderation-notice__actions" data-gs-scope="moderation-notice" data-gs-part="actions">
          {onReply ? (
            <button
              type="button"
              className="gs-moderation-notice__entry gs-action-type gs-pressable"
              data-gs-scope="moderation-notice" data-gs-part="control"
              data-gs-menu="reply"
              onClick={onReply}
            >
              {copy['moderation-notice.replyLabel']}
            </button>
          ) : null}
          {onReport ? (
            <button
              type="button"
              className="gs-moderation-notice__entry gs-action-type gs-pressable"
              data-gs-scope="moderation-notice" data-gs-part="control"
              data-gs-menu="report"
              onClick={onReport}
            >
              {copy['moderation-notice.reportLabel']}
            </button>
          ) : null}
          {onBlock ? (
            <button
              type="button"
              className="gs-moderation-notice__entry gs-action-type gs-pressable"
              data-gs-scope="moderation-notice" data-gs-part="control"
              data-gs-menu="block"
              data-gs-destructive="true"
              onClick={onBlock}
            >
              <span className="gs-moderation-notice__dot" aria-hidden="true" />
              {author === undefined
                ? copy['moderation-notice.blockLabel']
                : copy['moderation-notice.blockLabelFor'](author)}
            </button>
          ) : null}
        </div>
        {children}
      </div>
    )
  }

  return (
    <div
      {...rest}
      className={['gs-moderation-notice', className].filter(Boolean).join(' ')}
      data-gs-component="moderation-notice"
      data-gs-presentation="notice"
      data-gs-moderation={moderation}
      // Status rather than alert: a refusal is not an emergency, and a player
      // reading the room should not be interrupted mid-sentence by one.
      role="status"
    >
      <span
        className="gs-moderation-notice__glyph"
        data-gs-scope="moderation-notice" data-gs-part="glyph"
        data-gs-animates="emphasis"
        aria-hidden="true"
      >
        {refused ? <CrossGlyph /> : HELD_MARK}
      </span>
      <div className="gs-moderation-notice__column">
        <span className="gs-moderation-notice__heading" data-gs-scope="moderation-notice" data-gs-part="label">
          {heading ?? (refused ? copy['moderation-notice.refusedHeading'] : copy['moderation-notice.heldHeading'])}
        </span>
        <span className="gs-moderation-notice__body" data-gs-scope="moderation-notice" data-gs-part="reason">
          {reason ?? (refused ? copy['moderation-notice.refusedBody'] : copy['moderation-notice.heldBody'])}
        </span>
        {rules !== undefined ? (
          <span className="gs-moderation-notice__rules" data-gs-scope="moderation-notice" data-gs-part="note">
            {rules}
          </span>
        ) : null}
        {children}
      </div>
    </div>
  )
}

/* ModerationNotice. Every value comes from a token; nothing here is a literal
   colour.

   Specimen 6d draws both treatments: a padded surface card outlined in the
   colour of the state, and a column of three 48px entries. 48 is the touch
   floor and every entry meets it, because these three are the controls a
   player reaches for while they are already annoyed. */

.gs-moderation-notice {
  display: flex;
  gap: var(--gs-space-3);
  padding: var(--gs-space-inset);

  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-md);
}

.gs-moderation-notice__column {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-1);
  min-width: 0;
}

.gs-moderation-notice__glyph {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  box-sizing: border-box;
  width: var(--gs-size-control-small);
  height: var(--gs-size-control-small);

  font-family: var(--gs-type-display-font-family);
  font-size: var(--gs-type-title-font-size);
  line-height: 1;

  border-radius: var(--gs-radius-full);
  transition: color var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

.gs-moderation-notice__heading {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
  color: var(--gs-color-ink);
}

.gs-moderation-notice__body {
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);
  color: var(--gs-color-ink-secondary);
}

.gs-moderation-notice__rules {
  margin-top: var(--gs-space-1);
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-selected);
}

/* -- which notice ---------------------------------------------------------- */

/* Refused: the negative outline, a cross in a filled disc. Three changes at
   once with the heading's own words, per BDS-012. */
.gs-moderation-notice[data-gs-moderation='refused'] { border-color: var(--gs-color-negative-base); }

.gs-moderation-notice[data-gs-moderation='refused'] .gs-moderation-notice__glyph {
  color: var(--gs-color-on-accent);
  background: var(--gs-color-negative);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-negative-base);
  font-size: var(--gs-size-icon-utility);
}

/* Held: warning, and an outline rather than a fill, because it may still
   post and a filled negative disc would read as a refusal. */
.gs-moderation-notice[data-gs-moderation='held'] { border-color: var(--gs-color-warning); }

.gs-moderation-notice[data-gs-moderation='held'] .gs-moderation-notice__glyph {
  color: var(--gs-color-warning);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-warning);
}

/* -- the menu -------------------------------------------------------------- */

.gs-moderation-notice[data-gs-presentation='menu'] { flex-direction: column; }

.gs-moderation-notice__actions {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-2);
}

/* Worded, left-aligned, and 48px each. A row of bare icons puts report and
   block one slip apart, and the words are what stop that. */
.gs-moderation-notice__entry {
  display: flex;
  align-items: center;
  gap: var(--gs-space-gap);
  box-sizing: border-box;
  height: var(--gs-size-touch-min);
  padding: 0 var(--gs-space-inset);
  text-align: left;
  cursor: pointer;

  font-size: var(--gs-type-body-font-size);

  color: var(--gs-color-ink);
  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-sm);
}

.gs-moderation-notice__entry:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

/* The one entry that changes what the player sees from now on carries the
   negative outline and a mark, so it does not rest on its wording alone. */
.gs-moderation-notice__entry[data-gs-destructive='true'] {
  border-color: var(--gs-color-negative-base);
}

.gs-moderation-notice__dot {
  flex: none;
  box-sizing: border-box;
  width: var(--gs-size-icon-utility);
  height: var(--gs-size-icon-utility);
  background: var(--gs-color-negative);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-negative-base);
  border-radius: var(--gs-radius-full);
}
